    <div class="container">
        <header>
            <h1>JiMesh - LLM Mesh Router</h1>
            <p class="subtitle">FreeLLMAPI-based intelligent model routing</p>
        </header>

        <section class="section">
            <h2>🎯 Default Tier Chains</h2>
            <div class="stats-grid" id="tierStats">
                <div class="stat-card s-tier">
                    <div class="tier-name">S-Tier</div>
                    <div class="tier-count" id="sCount">-</div>
                    <div class="tier-desc">Top intelligence models</div>
