                <p><strong>Server URL:</strong> <a href="http://localhost:3010" id="serverUrl">http://localhost:3010</a></p>
                <p><strong>API Key:</strong> <code id="apiKey">freellmapi-25570d9ede4036a99a805826a0e8b8c67c77f349d513df99</code></p>
                <p><strong>Status:</strong> <span id="serverStatus" class="loading">Checking...</span></p>
            </div>
        </section>

        <section class="section">
            <h2>📋 Provider Requirements</h2>
            <p style="color: #94a3b8; margin-bottom: 1rem;">
                API keys required for full tier chain functionality
            </p>
            <div class="provider-grid" id="providerList">
                <div style="text-align: center; color: #94a3b8; padding: 2rem;">
                    Loading provider requirements...
                </div>
            </div>
        </section>

        <section class="section">
            <h2>📚 API Documentation</h2>
            <p style="color: #94a3b8;">
                <a href="/docs">/docs</a> - API Documentation<br>
                <a href="/v1/models">/v1/models</a> - Available Models<br>
                <a href="/status">/status</a> - System Status
            </p>
        </section>
    </div>

    <script>
        // Tier statistics
        const tierData = {
            's-tier': { count: 16, name: 'S-Tier', desc: 'Top intelligence models for critical tasks' },
            'a-tier': { count: 69, name: 'A-Tier', desc: 'High quality models for most tasks' },
            'b-tier': { count: 241, name: 'B-Tier', desc: 'Good models for simple/fast tasks' }
        };

        // Update tier statistics
        function updateTierStats() {
            const tiers = ['s-tier', 'a-tier', 'b-tier'];
            let total = 0;
            tiers.forEach(tier => {
                const data = tierData[tier];
                document.getElementById(tier + 'Count').textContent = data.count;
                total += data.count;
            });
            document.getElementById('totalModels').textContent = total.toLocaleString();
        }

        // Provider requirements data
        const providerRequirements = {
            version: "1.0.0",
            providers: {
                navy: { platform: "navy", tiers: ["s-tier", "a-tier", "b-tier"], model_count: 104, priority: "critical" },
                huggingface: { platform: "huggingface", tiers: ["s-tier", "a-tier", "b-tier"], model_count: 24, priority: "critical" },
                cloudflare: { platform: "cloudflare", tiers: ["a-tier", "b-tier"], model_count: 21, priority: "high" },
                nvidia: { platform: "nvidia", tiers: ["s-tier", "a-tier", "b-tier"], model_count: 19, priority: "critical" },
                aihorde: { platform: "aihorde", tiers: ["b-tier"], model_count: 15, priority: "medium" },
                ovh: { platform: "ovh", tiers: ["a-tier", "b-tier"], model_count: 14, priority: "high" },
                mistral: { platform: "mistral", tiers: ["b-tier"], model_count: 13, priority: "medium" },
                modelscope: { platform: "modelscope", tiers: ["s-tier", "a-tier", "b-tier"], model_count: 11, priority: "critical" },
                cohere: { platform: "cohere", tiers: ["b-tier"], model_count: 11, priority: "medium" },
                google: { platform: "google", tiers: ["s-tier", "b-tier"], model_count: 10, priority: "critical" },
                kilo: { platform: "kilo", tiers: ["a-tier", "b-tier"], model_count: 10, priority: "high" },
                groq: { platform: "groq", tiers: ["a-tier", "b-tier"], model_count: 9, priority: "high" },
                requesty: { platform: "requesty", tiers: ["a-tier", "b-tier"], model_count: 8, priority: "high" },
                openrouter: { platform: "openrouter", tiers: ["b-tier"], model_count: 8, priority: "medium" },
                ollama: { platform: "ollama", tiers: ["a-tier", "b-tier"], model_count: 7, priority: "high" },
                opencode: { platform: "opencode", tiers: ["a-tier", "b-tier"], model_count: 7, priority: "high" },
                aion: { platform: "aion", tiers: ["b-tier"], model_count: 5, priority: "medium" },
                sealion: { platform: "sealion", tiers: ["b-tier"], model_count: 5, priority: "medium" },
                ainative: { platform: "ainative", tiers: ["a-tier", "b-tier"], model_count: 4, priority: "high" },
                nara: { platform: "nara", tiers: ["b-tier"], model_count: 4, priority: "medium" },
                cerebras: { platform: "cerebras", tiers: ["a-tier", "b-tier"], model_count: 3, priority: "high" },
                llm7: { platform: "llm7", tiers: ["b-tier"], model_count: 3, priority: "medium" },
                routeway: { platform: "routeway", tiers: ["b-tier"], model_count: 3, priority: "medium" },
                zhipu: { platform: "zhipu", tiers: ["b-tier"], model_count: 3, priority: "medium" },
                agnes: { platform: "agnes", tiers: ["b-tier"], model_count: 2, priority: "medium" },
                reka: { platform: "reka", tiers: ["b-tier"], model_count: 2, priority: "medium" },
                bazaarlink: { platform: "bazaarlink", tiers: ["b-tier"], model_count: 1, priority: "medium" }
            }
        };

        // Update provider list
        function updateProviderList() {
            const container = document.getElementById('providerList');
            container.innerHTML = '';

            const providers = Object.entries(providerRequirements.providers);

            // Sort by priority and model count
            const sortedProviders = providers.sort((a, b) => {
                const priorityOrder = { critical: 0, high: 1, medium: 2 };
                const aPriority = priorityOrder[a[1].priority] || 3;
                const bPriority = priorityOrder[b[1].priority] || 3;
                if (aPriority !== bPriority) return aPriority - bPriority;
                return b[1].model_count - a[1].model_count;
            });

            sortedProviders.forEach(([key, provider]) => {
                const card = document.createElement('div');
                card.className = `provider-card priority-${provider.priority}`;

                const priorityClass = provider.priority === 'critical' ? 'critical' : 
                                      provider.priority === 'high' ? 'high' : 'medium';

                card.innerHTML = `
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;">
                        <strong style="font-size: 1.1rem; color: #f1f5f9;">${provider.platform}</strong>
                        <span class="priority-tag ${priorityClass}">${provider.priority.toUpperCase()}</span>
                    </div>
                    <p style="color: #94a3b8; font-size: 0.9rem; margin-bottom: 0.5rem;">
                        ${provider.model_count} models
                    </p>
                    <p style="color: #94a3b8; font-size: 0.85rem;">
                        Tiers: ${provider.tiers.join(', ')}
                    </p>
                `;
                container.appendChild(card);
            });
        }

        // Check server status
        async function checkServerStatus() {
            const statusEl = document.getElementById('serverStatus');
            statusEl.textContent = 'Checking...';
            statusEl.className = 'loading';

            try {
                const response = await fetch('http://localhost:3010/status', {
                    headers: { 'Authorization': 'Bearer freellmapi-25570d9ede4036a99a805826a0e8b8c67c77f349d513df99' }
                });
                if (response.ok) {
                    statusEl.textContent = 'Online ✓';
                    statusEl.className = 'success';
                } else {
                    statusEl.textContent = 'Error: ' + response.status;
                    statusEl.className = 'error';
                }
            } catch (error) {
                statusEl.textContent = 'Offline';
                statusEl.className = 'error';
            }
        }

        // Initialize
        updateTierStats();
        updateProviderList();
        checkServerStatus();

        // Auto-refresh server status every 30 seconds
        setInterval(checkServerStatus, 30000);
    </script>
</body>
</html>
EOF
